# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots", type: :request do
  it "refuses over HTTP a higher-version snapshot that moves company A's entry to company B and leaves the row unchanged" do
    company_a = create(:company)
    company_b = create(:company)
    user = create(:user)
    create(:employment, company: company_a, user:)
    create(:employment, company: company_b, user:)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    stored = create(:timesheet_entry, user:, project: project_a, note: "Company A private note")
    fields_before = stored.reload.attributes
    expect(fields_before["company_id"]).to eq(company_a.id)

    contract = TimekeepingContract.load(:entry_snapshots)
    entry = contract.fetch("entry_fields").index_with(nil).merge(
      "id" => stored.id, "company_id" => company_b.id, "version" => fields_before["version"] + 5,
      "project_id" => project_b.id, "user_id" => user.id, "work_date" => "2026-03-02", "duration" => 90.0,
      "note" => "moved to company B", "bill_status" => "unbilled", "review_status" => "not_required",
      "locked" => false, "source" => "manual", "source_metadata" => {}, "proof_metadata" => {},
      "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z"
    )
    batch = {
      "schema_version" => contract.fetch("schema_version"),
      "snapshots" => [{ "generation" => TimekeepingOwnership.current.generation, "outbox_position" => 1, "entry" => entry }]
    }

    with_timekeeping_service_token do |token|
      post "/internal/v1/timekeeping/entry-snapshots", params: batch.to_json, headers: {
        "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
        "Idempotency-Key" => SecureRandom.uuid
      }
    end

    # "A snapshot whose `company_id` differs from the row's is refused."
    # The issue names no status for this refusal; the plan answers it as a
    # stale batch, 409 stale_generation, and never names the stored company.
    expect(response).to have_http_status(409)
    expect(response.parsed_body).to eq("reason" => "stale_generation")
    expect(response.body).not_to include(company_a.id.to_s.then { |id| "\"company_id\":#{id}" })
    expect(stored.reload.attributes).to eq(fields_before)
    expect(company_b.timesheet_entries.where(id: stored.id)).to be_empty
  end
end
